import bisect

class Solution:
    def matrixMedian(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        low = min(row[0] for row in grid)
        high = max(row[-1] for row in grid)
        needed = (m * n + 1) // 2

        while low < high:
            mid = (low + high) // 2
            cnt = sum(bisect.bisect_right(row, mid) for row in grid)
            if cnt < needed:
                low = mid + 1
            else:
                high = mid
        return low

class Solution {
public:
    int matrixMedian(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int low = grid[0][0], high = grid[0][n - 1];
        for (int i = 0; i < m; i++) {
            low = std::min(low, grid[i][0]);
            high = std::max(high, grid[i][n - 1]);
        }
        int needed = (m * n + 1) / 2;

        while (low < high) {
            int mid = low + (high - low) / 2;
            int cnt = 0;
            for (int i = 0; i < m; i++) {
                cnt += std::upper_bound(grid[i].begin(), grid[i].end(), mid) - grid[i].begin();
            }
            if (cnt < needed) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
};

class Solution {
    public int matrixMedian(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int low = grid[0][0], high = grid[0][n - 1];
        for (int i = 0; i < m; i++) {
            low = Math.min(low, grid[i][0]);
            high = Math.max(high, grid[i][n - 1]);
        }
        int needed = (m * n + 1) / 2;

        while (low < high) {
            int mid = low + (high - low) / 2;
            int cnt = 0;
            for (int i = 0; i < m; i++) {
                cnt += countLE(grid[i], mid);
            }
            if (cnt < needed) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    private int countLE(int[] row, int target) {
        int l = 0, r = row.length;
        while (l < r) {
            int m = l + (r - l) / 2;
            if (row[m] <= target) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

var matrixMedian = function(grid) {
    const m = grid.length, n = grid[0].length;
    let low = grid[0][0], high = grid[0][n - 1];
    for (let i = 0; i < m; i++) {
        low = Math.min(low, grid[i][0]);
        high = Math.max(high, grid[i][n - 1]);
    }
    const needed = Math.floor((m * n + 1) / 2);

    function countLE(row, target) {
        let l = 0, r = row.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (row[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let cnt = 0;
        for (let i = 0; i < m; i++) {
            cnt += countLE(grid[i], mid);
        }
        if (cnt < needed) low = mid + 1;
        else high = mid;
    }
    return low;
};
